import{z as l,x as B,o as E,c as A,q as r,j as i,D as e,d as n,s as o,S as s}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"后缀树","description":"","frontmatter":{"title":"后缀树","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/suffix-tree.md","filePath":"cs/suffix-tree.md","lastUpdated":1791413859000}'),d={name:"cs/suffix-tree.md"};function p(c,a,D,_,h,f){const t=B("Mermaid");return E(),A("div",null,[a[2]||(a[2]=r('<h1 id="后缀树" tabindex="-1">后缀树 <a class="header-anchor" href="#后缀树" aria-label="Permalink to &quot;后缀树&quot;">​</a></h1><div class="epigraph"><p>压缩 trie 挂上文本的全部后缀；从根到叶的路径标出一条后缀，子串查询变成沿边走字符。</p><footer>—— 据 Weiner, Linear Pattern Matching Algorithms, SWAT 1973；Ukkonen, On-Line Construction of Suffix Trees, Algorithmica 1995；Gusfield, Algorithms on Strings, Trees, and Sequences 整理</footer></div><p><a href="/cs/lcp-kasai">上一课</a> 用数组隐式表达相邻 lcp。需要显式 coprime 边、后缀链、或 \\(O(|P|)\\) 查找（字母表常数时），树更直接。<a href="/cs/trie">Trie</a> 不压缩会 \\(\\Theta(n^2)\\) 节点。本课不重写 Kasai 循环。缺口是后缀树：压缩后缀 trie，线性节点。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>每个内部节点对应某子串的全体出现的分支点；边用 \\(T\\) 的下标对表示（不拷字符）。叶对应后缀。查询 \\(P\\)：从根沿边匹配，失败则 \\(P\\) 不是子串，成功则子树叶即出现位置。缺口是<strong>线性规模的显式后缀 trie</strong>，以及后缀链（内部节点连到较短后缀）支撑线性构造。</p><p><span class="marginnote">术语翻译：压缩 trie 就是把「只有一个孩子的链式路径」合并成一整条边，边上不复制字符、只记「取原文第 \\(l\\) 到 \\(r\\) 个字符」的下标对。节点数因此从 \\(\\Theta(n^2)\\) 降到 \\(O(n)\\)。</span></p><p><span class="marginnote">Weiner 1973 离线线性；McCreight 更省；Ukkonen 在线。Gusfield 书是串算法标准叙述。本课钉结构与查询，不默写 Ukkonen 全部活动点 case。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>查询 \\(O(|P|)\\) 字符比较（边跳过用长度）。出现次数 = 子树叶数，可预处理 size。LCE、最长重复：最深内部节点。与 \\(SA+LCP\\)：后缀树可用前者隐式模拟，空间常更大但指针语义清楚。</p>',9)),(E(),i(s,null,{default:e(()=>[o(t,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20ROOT%5B%22%E6%A0%B9%22%5D%20--%3E%20EDGE%5B%22%E8%BE%B9%20%3D%20T%20%E7%9A%84%E5%8C%BA%E9%97%B4%22%5D%0A%20%20EDGE%20--%3E%20INT%5B%22%E5%86%85%E9%83%A8%3A%20%E5%88%86%E6%94%AF%22%5D%0A%20%20EDGE%20--%3E%20LEAF%5B%22%E5%8F%B6%3A%20%E4%B8%80%E6%9D%A1%E5%90%8E%E7%BC%80%22%5D%0A%20%20LINK%5B%22%E5%90%8E%E7%BC%80%E9%93%BE%22%5D%20--%3E%20INT%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r('<p>构造：教学可用 \\(O(n\\log n)\\) 插后缀 + 压缩；线性算法承认存在。字母表大时边表用 map，时间多 \\(\\log|\\Sigma|\\)。</p><p><span class="marginnote">数字实例：\\(T=\\) <code>banana</code>，查 <code>an</code>。从根走到标着 <code>ana</code> 的边（下标对 1..3），按边逐字符比对，<code>an</code> 在边中途走完——落在内部节点 <code>ana</code> 上，其子树叶有 2 片，即出现次数 2，出现位置就是那两片叶对应的后缀起点。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>压缩：一元路径合成边，节点 \\(O(n)\\)。正确性：全体后缀恰好覆盖所有子串（子串是某后缀前缀）。不要存每条边的显式字符串拷贝。</p><p>一次 \\(O(|P|)\\) 查询沿树走的完整过程。</p>',5)),(E(),i(s,null,{default:e(()=>[o(t,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20ST%5B%22%E4%BB%8E%E6%A0%B9%E5%87%BA%E5%8F%91%EF%BC%8Ci%20%3D%200%22%5D%20--%3E%20ED%7B%22%E5%BD%93%E5%89%8D%E8%BE%B9%E6%98%AF%E4%B8%8B%E6%A0%87%E5%AF%B9%EF%BC%8C%E9%80%90%E5%AD%97%E7%AC%A6%E6%AF%94%20P%5Bi%5D%22%7D%0A%20%20ED%20--%20%22%E8%BE%B9%E8%B5%B0%E5%AE%8C%22%20--%3E%20NX%7B%22P%20%E4%B9%9F%E8%B5%B0%E5%AE%8C%E4%BA%86%E5%90%97%22%7D%0A%20%20NX%20--%20%22%E6%B2%A1%E6%9C%89%22%20--%3E%20SJ%5B%22%E8%B7%B3%E5%88%B0%E4%B8%8B%E4%B8%80%E6%9D%A1%E8%BE%B9%E7%BB%A7%E7%BB%AD%E6%AF%94%22%5D%0A%20%20SJ%20--%3E%20ED%0A%20%20NX%20--%20%22%E6%98%AF%22%20--%3E%20HIT%5B%22%E5%AD%90%E6%A0%91%E5%8F%B6%E6%95%B0%E5%8D%B3%E5%87%BA%E7%8E%B0%E4%BD%8D%E7%BD%AE%22%5D%0A%20%20ED%20--%20%22%E5%AD%97%E7%AC%A6%E5%A4%B1%E9%85%8D%22%20--%3E%20MISS%5B%22P%20%E4%B8%8D%E6%98%AF%E5%AD%90%E4%B8%B2%EF%BC%8C%E6%9F%A5%E8%AF%A2%E7%BB%93%E6%9D%9F%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=r('<p><span class="marginnote">初学者容易以为每条边要真的存一段字符串副本；实际只存 \\((l,r)\\) 两个下标，比较时回原文取字符。这既是空间 \\(O(n)\\) 的原因，也是「查询时间只和 \\(|P|\\) 有关、和树多大无关」的关键。</span></p><p>与后课 SAM：自动机把结束位置等价类收成更少状态，后缀树节点与 SAM 状态有对应，本课不提前最小化。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 Weiner 证明写完。外存后缀树难；实践大文本用 \\(SA\\)。回文结构不是后缀树默认合同。</p><p>后课默认：要显式后缀 trie 用后缀树。要最小接受全部后缀的自动机，用 SAM。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>后缀树：压缩后缀 trie，查询 \\(O(|P|)\\)，节点 \\(O(n)\\)。</li><li>边存下标对；后缀链服务构造。</li><li>最小后缀自动机是下一课。</li><li>出处：Weiner, 1973；Ukkonen, 1995；Gusfield。</li></ul>',7))])}const u=l(d,[["render",p]]);export{T as __pageData,u as default};
